/* prog23_longest_common_prefix.c
 * Reimplementation of the original binary's behaviour.
 *
 * Behaviour:
 *   - If more than 65 arguments are supplied (including the program name)
 *       prints "TOO_MANY".
 *   - If no arguments are supplied (argc == 1)
 *       prints "EMPTY".
 *   - If any argument is longer than 1024 characters
 *       prints "TOO_LONG".
 *   - Otherwise prints the longest common prefix of all arguments,
 *       followed by a newline (empty line if the prefix is empty).
 *
 * The program never reads from stdin and always returns 0.
 */

#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    /* 1. Argument count checks */
    if (argc > 65) {               /* 0x41 == 65 */
        puts("TOO_MANY");
        return 0;
    }
    if (argc < 2) {                /* only program name */
        puts("EMPTY");
        return 0;
    }

    /* 2. Length limit check (0x400 == 1024) */
    const size_t MAX_LEN = 1024;
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* 3. Compute longest common prefix */
    const char *prefix = argv[1];
    size_t prefix_len = strlen(prefix);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && prefix[j] == s[j]) {
            ++j;
        }
        prefix_len = j;                 /* shrink to the common part */
        if (prefix_len == 0) {
            break;                      /* no common prefix any more */
        }
    }

    /* 4. Output the prefix (character by character, then newline) */
    for (size_t i = 0; i < prefix_len; ++i) {
        putc(prefix[i], stdout);
    }
    putc('\n', stdout);

    return 0;
}
